import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ServerPlayerPostMovePosition{Position: mgl32.Vec3{-1.5, 0.25, 1024.5}}
POSITION = bytes.fromhex("0000c0bf0000803e00108044")

# generated by gophertunnel b8bd735:
# &packet.ServerPlayerPostMovePosition{Position: mgl32.Vec3{3.4e38, -3.4e38, 1e-8}}
EXTREMES = bytes.fromhex("9ec97f7f9ec97fff77cc2b32")

GOLDENS = [
    pytest.param(
        v2225.ServerPlayerPostMovePositionPacket(pos=v2225.Vec3(x=-1.5, y=0.25, z=1024.5)),
        POSITION,
        id="position",
    ),
    pytest.param(
        v2225.ServerPlayerPostMovePositionPacket(pos=v2225.Vec3(x=3.4e38, y=-3.4e38, z=1e-8)),
        EXTREMES,
        id="extremes",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_server_player_post_move_position_is_packet_16(version):
    assert version.PACKETS[16] is version.ServerPlayerPostMovePositionPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_player_post_move_position_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_player_post_move_position_decodes_from_its_golden(packet, golden):
    assert v2225.ServerPlayerPostMovePositionPacket.from_bytes(golden) == packet


def test_server_player_post_move_position_rejects_a_truncated_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.ServerPlayerPostMovePositionPacket.from_bytes(POSITION[:11])
